package cc.nimbus.event.impl.player;
import cc.nimbus.event.Cancelable;
import cc.nimbus.event.EventType;
public class EventMotion extends Cancelable { private double posX,posY,posZ; private float yaw,pitch,cameraYaw,cameraPitch; private boolean ground; private EventType type; public EventMotion(){} public EventMotion(double x,double y,double z,float yaw,float pitch,float cameraYaw,float cameraPitch,boolean ground,EventType type){set(x,y,z,yaw,pitch,cameraYaw,cameraPitch,ground,type);} public EventMotion set(double x,double y,double z,float yaw,float pitch,float cameraYaw,float cameraPitch,boolean ground,EventType type){reset();posX=x;posY=y;posZ=z;this.yaw=yaw;this.pitch=pitch;this.cameraYaw=cameraYaw;this.cameraPitch=cameraPitch;this.ground=ground;this.type=type;return this;} public double getPosX(){return posX;} public void setPosX(double v){posX=v;} public double getPosY(){return posY;} public void setPosY(double v){posY=v;} public double getPosZ(){return posZ;} public void setPosZ(double v){posZ=v;} public float getYaw(){return yaw;} public void setYaw(float v){yaw=v;} public float getPitch(){return pitch;} public void setPitch(float v){pitch=v;} public float getCameraYaw(){return cameraYaw;} public float getCameraPitch(){return cameraPitch;} public void setRotation(float y,float p){yaw=y;pitch=p;} public boolean isGround(){return ground;} public void setGround(boolean v){ground=v;} public EventType getType(){return type;} public boolean isPre(){return type==EventType.PRE;} public boolean isPost(){return type==EventType.POST;} }
